# Simulation designs of the paper (Experiments A, B and C)
#
# Returns the process, the design sampler, the error variance and the
# regression function of each simulation design, for use with og_simulate.
# Experiment D (Brownian motion measured once) is generated by og_simulate_bm.
og_simulation_design <- function(experiment = c("A", "B", "C"), design = c("A", "B"),
                                 prob2 = 0.5, scenario = c("interaction", "usual"),
                                 delta = 0.45, sign = 1) {
  experiment <- match.arg(experiment)
  force(delta); force(sign)
  interaction <- function(V) 0.5 + sign * delta * sin(V[, 1]) * sin(V[, 2])
  if (experiment == "A") {
    design <- match.arg(design)
    phi <- function(t) cbind(sqrt(2) * cos(2 * pi * t), sqrt(2) * sin(2 * pi * t))
    sampler <- if (design == "A") function(n) as.list(sample(c(0, 0.25), n, replace = TRUE)) else
      og_design_sampler(1, support = 1)
    return(list(process = og_process_kl(c(0.5, 0.5), phi), design = sampler, sigma2 = 0,
                g = interaction, r = 2))
  }
  if (experiment == "B") {
    if (prob2 < 0 || prob2 > 1) stop("prob2 must lie in [0, 1]")
    H1 <- function(t) sqrt(2) * (pmin(t, 0.25) - pmin(pmax(t - 0.25, 0), 0.25))
    H2 <- function(t) sqrt(2) * (pmin(pmax(t - 0.5, 0), 0.25) - pmin(pmax(t - 0.75, 0), 0.25))
    return(list(process = og_process_bm(function(t) cbind(H1(t), H2(t))),
                design = og_design_sampler(c(1 - prob2, prob2), support = 1:2),
                sigma2 = 0.05, g = interaction, r = 2))
  }
  scenario <- match.arg(scenario)
  sc <- og_scenario(scenario, delta = delta)
  list(process = og_process_kl(c(1, 0.6, 0.35, 0.2), og_fourier_phi(4)),
       design = og_design_sampler(c(0.4, 0.3, 0.2, 0.1)), sigma2 = 0.1, g = sc$g, r = sc$r)
}
